import json, glob, pathlib, re
# Extract all text blocks from events files; test each line for parseable {"case_id","content"}
for f in sorted(glob.glob("out/events-ling-0*.jsonl")):
    n_text_parts = 0; n_lines=0; n_parseable=0; samples=[]
    for line in pathlib.Path(f).read_text().splitlines():
        e = json.loads(line)
        # find text parts
        parts = []
        if isinstance(e.get("part"), dict):
            parts=[e["part"]]
        # also message parts?
        msg = e.get("part", {})
        t = msg.get("type")
        txt = msg.get("text","") if isinstance(msg, dict) else ""
        if t=="text" and txt:
            n_text_parts+=1
            for ln in txt.splitlines():
                ln=ln.strip()
                if not ln: continue
                n_lines+=1
                try:
                    o=json.loads(ln)
                    if isinstance(o,dict) and "case_id" in o and "content" in o:
                        n_parseable+=1
                        samples.append(ln[:200])
                except Exception:
                    pass
    print(f"{f}: text_parts={n_text_parts} lines={n_lines} parseable_caseid_content={n_parseable}")
    for s in samples[:3]: print("   SAMPLE:", s)
EOF

